package com.wolinski.shop.payments.api;

import com.wolinski.shop.money.Money;
import com.wolinski.shop.payments.internal.Payment;
import java.util.List;

public interface PaymentsFacade {

    void charge(String orderId, Money amount);

    void refund(String orderId, Money amount);

    String status(String orderId);

    List<Payment> paymentsOf(String orderId);
}

package com.wolinski.shop.payments.internal;

import com.wolinski.shop.money.Money;
import com.wolinski.shop.payments.api.PaymentRefunded;
import com.wolinski.shop.payments.api.PaymentsFacade;
import java.time.Clock;
import java.util.List;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class PaymentService implements PaymentsFacade {

    private final PaymentRepository payments;
    private final Clock clock;
    private final ApplicationEventPublisher events;

    public PaymentService(PaymentRepository payments, Clock clock, ApplicationEventPublisher events) {
        this.payments = payments;
        this.clock = clock;
        this.events = events;
    }

    @Override
    @Transactional
    public void charge(String orderId, Money amount) {
        payments.save(new Payment(orderId, amount, clock.instant()));
    }

    @Override
    @Transactional
    public void refund(String orderId, Money amount) {
        List<Payment> found = payments.findByOrderId(orderId);
        found.getLast().addRefund(amount);
        events.publishEvent(new PaymentRefunded(orderId, amount));
    }

    @Override
    @Transactional(readOnly = true)
    public List<Payment> paymentsOf(String orderId) {
        return payments.findByOrderId(orderId);
    }

    @Override
    @Transactional(readOnly = true)
    public String status(String orderId) {
        return payments.findByOrderId(orderId).getLast().status();
    }
}

package com.wolinski.shop.payments.internal;

import com.wolinski.shop.money.Money;
import java.time.Instant;

public class Payment {

    private final String orderId;
    private final Money amount;
    private final Instant paidAt;
    private Money refunded;
    private String status = "CAPTURED";

    public Payment(String orderId, Money amount, Instant paidAt) {
        this.orderId = orderId;
        this.amount = amount;
        this.paidAt = paidAt;
        this.refunded = new Money(0, amount.currency());
    }

    public String orderId() {
        return orderId;
    }

    public Money amount() {
        return amount;
    }

    public Instant paidAt() {
        return paidAt;
    }

    public Money refunded() {
        return refunded;
    }

    public String status() {
        return status;
    }

    public void addRefund(Money amount) {
        refunded = refunded.plus(amount);
        status = "REFUNDED";
    }
}

package com.wolinski.shop.payments.internal;

import com.wolinski.shop.money.Money;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import org.springframework.stereotype.Repository;

@Repository
public class PaymentRepository {

    private final Map<String, List<Payment>> payments = new ConcurrentHashMap<>();

    public void save(Payment payment) {
        payments.computeIfAbsent(payment.orderId(), id -> new ArrayList<>()).add(payment);
    }

    public List<Payment> findByOrderId(String orderId) {
        return payments.getOrDefault(orderId, List.of());
    }

    public Money refundedFor(String orderId) {
        return findByOrderId(orderId).stream()
                .map(Payment::refunded)
                .reduce(Money::plus)
                .orElse(Money.pln(0));
    }
}

